// ===== Parse + Dedupe + Pre-check + Rank Top-N =====
const items = $input.all();
const seen = new Set();
const candidates = [];
const stats = {
  total: items.length,
  deduped: 0,
  tooOld: 0,
  noTitle: 0,
  belowMinScore: 0,
  kept: 0,
  droppedBelowTopN: 0,
};

// ⚙️ ปรับได้
const MAX_AGE_HOURS = 48;
const MIN_PRE_SCORE = 2;   // ต้องมีอย่างน้อย 1 signal ชัดเจน
const TOP_N = 5;            // ส่งเข้า Ollama เฉพาะ Top N ข่าวสำคัญสุดต่อรอบ

for (const item of items) {
  const title   = item.json.title   || '';
  const link    = item.json.link    || item.json.url || '';
  const content = item.json.contentSnippet || item.json.content || item.json.summary || item.json.description || '';
  const pubDate = item.json.pubDate || item.json.isoDate || new Date().toISOString();
  const source  = item.json.feedUrl || link.split('/').slice(0,3).join('/');

  if (!title) { stats.noTitle++; continue; }

  const key = title.toLowerCase().trim();
  if (seen.has(key)) { stats.deduped++; continue; }
  seen.add(key);

  const ageHours = (Date.now() - new Date(pubDate).getTime()) / 36e5;
  if (ageHours > MAX_AGE_HOURS) { stats.tooOld++; continue; }

  // รวม title + content เพื่อตรวจ signal (เพราะ title มัก carry impact keyword)
  const text = `${title}\n${content}`;

  const signals = {
    has_named_source  : /said|according to|told reporters|confirmed by|spokesperson/i.test(text),
    has_url_link      : /https?:\/\//i.test(content),
    has_onchain_ref   : /etherscan|dune analytics|blockchair|token terminal|glassnode/i.test(text),
    has_anonymous_src : /sources say|reportedly|rumored|unconfirmed|insiders say/i.test(text),
    has_official_doc  : /filing|sec|cftc|statement|press release|announcement|whitepaper/i.test(text),
    has_named_person  : /CEO|CTO|CFO|founder|chairman|minister|senator/i.test(text),
    // ⭐ impact keyword: เหตุการณ์ที่มีผลกระทบต่อตลาด
    has_impact_keyword: /SEC|ETF|hack|exploit|lawsuit|launch|halving|partnership|listed|delisted|approved|rejected|Fed|FOMC|regulation|\bban\b|bankruptcy|merger|acquisition/i.test(text),
    // ⭐ major coin mention เพิ่ม weight
    mentions_major_coin: /\b(BTC|Bitcoin|ETH|Ethereum|SOL|Solana|BNB|XRP|Ripple|ADA|Cardano|DOGE)\b/i.test(text)
  };

  const positive_signals = [
    signals.has_named_source,
    signals.has_url_link,
    signals.has_onchain_ref,
    signals.has_official_doc,
    signals.has_named_person
  ].filter(Boolean).length;

  const impact_bonus    = signals.has_impact_keyword ? 2 : 0;
  const major_coin_bonus= signals.mentions_major_coin ? 1 : 0;
  const anonymous_penalty = signals.has_anonymous_src ? 1 : 0;

  const pre_score = Math.max(
    0,
    Math.min(10, positive_signals * 2 + impact_bonus + major_coin_bonus - anonymous_penalty)
  );

  if (pre_score < MIN_PRE_SCORE) { stats.belowMinScore++; continue; }

  candidates.push({
    title,
    link,
    content: content.slice(0, 2000),
    pubDate,
    source,
    attribution_signals: signals,
    pre_score
  });
}

// 🏆 เรียง pre_score มาก → น้อย และหยิบเฉพาะ Top N
candidates.sort((a, b) => b.pre_score - a.pre_score);
const selected = candidates.slice(0, TOP_N);
stats.kept = selected.length;
stats.droppedBelowTopN = Math.max(0, candidates.length - selected.length);

console.log('📊 Parse stats:', JSON.stringify(stats));

return selected.map(c => ({ json: { ...c, _stats: stats } }));

const item = $input.item.json;

const signalSummary = Object.entries(item.attribution_signals)
  .map(([k, v]) => `- ${k}: ${v}`)
  .join('\n');

const prompt = `คุณเป็นนักวิเคราะห์ข่าว crypto ที่เชี่ยวชาญ ประเมินข่าวต่อไปนี้และตอบกลับเป็น JSON เท่านั้น ห้ามมีข้อความอื่นนอกจาก JSON ห้ามใช้ markdown code fence

ชื่อข่าว: ${item.title}
แหล่งที่มา: ${item.source}
เนื้อหา: ${item.content}

ผล pre-check (regex):
${signalSummary}
pre_score: ${item.pre_score}/10

⚠️ สำคัญ: เนื้อหาที่ได้คือ RSS snippet (สรุปสั้น) ไม่ใช่บทความเต็ม
- อย่าลงโทษคะแนน attribution หนักเกินไปเพราะเนื้อหาสั้น
- ประเมินจากชื่อข่าว + แหล่งที่มาที่น่าเชื่อถือ (CoinDesk, CoinTelegraph, Decrypt เป็น tier-1 sources) + signals ที่ตรวจพบ
- แหล่งข่าวระดับ tier-1 ให้คะแนน baseline 6/10 ขึ้นไป
- credibility "Low" สงวนไว้สำหรับข่าวที่มี red flag ชัดเจน หรือเป็น rumor/unconfirmed เท่านั้น

ตอบ JSON รูปแบบนี้เท่านั้น:
{
  "summary_th": "สรุปข่าวภาษาไทย 2-3 ประโยค",
  "sentiment": "Bullish | Bearish | Neutral",
  "sentiment_reason": "เหตุผลสั้นๆ",
  "coins_mentioned": ["BTC"],
  "source_attribution_score": 7,
  "source_attribution_notes": "หมายเหตุ",
  "red_flags": [],
  "credibility": "High",
  "recommended_action": "ควรติดตามต่อหรือไม่"
}`;

return { json: { ...item, ollama_prompt: prompt } };

// $input.item.json = Ollama response (replaces input)
// → ดึงข้อมูลข่าวเดิมจาก node ก่อนหน้าผ่าน $('Build Ollama Prompt1').item.json
const ollama = $input.item.json;
const original = $('Build Ollama Prompt1').item.json;

let analysis = {};
let parseOk = false;

try {
  let raw = ollama.response || '';
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON found in response');

  analysis = JSON.parse(match[0]);
  parseOk = true;

  let score = Number(analysis.source_attribution_score);
  if (!Number.isFinite(score)) score = 5;
  analysis.source_attribution_score = Math.max(0, Math.min(10, score));

  const cred = String(analysis.credibility || '').trim();
  if (!['High', 'Medium', 'Low'].includes(cred)) analysis.credibility = 'Medium';

  const sent = String(analysis.sentiment || '').trim();
  if (!['Bullish', 'Bearish', 'Neutral'].includes(sent)) analysis.sentiment = 'Neutral';

  if (!Array.isArray(analysis.coins_mentioned)) analysis.coins_mentioned = [];
  if (!Array.isArray(analysis.red_flags)) analysis.red_flags = [];
} catch (e) {
  console.log('⚠️ Parse error for:', original.title, '-', e.message);
  analysis = {
    summary_th              : original.title + ' (ไม่สามารถวิเคราะห์เนื้อหาได้ - ใช้ข้อมูลเดิม)',
    sentiment               : 'Neutral',
    sentiment_reason        : 'AI ตอบกลับไม่ถูก format',
    coins_mentioned         : [],
    source_attribution_score: 5,
    source_attribution_notes: 'Parse error: ' + e.message,
    red_flags               : ['ai_parse_error'],
    credibility             : 'Medium',
    recommended_action      : 'AI ตอบกลับ JSON ไม่ถูกต้อง ควรตรวจสอบเนื้อหาด้วยตนเอง'
  };
}

return {
  json: {
    title       : original.title,
    link        : original.link,
    source      : original.source,
    pubDate     : original.pubDate,
    pre_score   : original.pre_score,
    parse_ok    : parseOk,
    ...analysis,
    analyzed_at : new Date().toISOString()
  }
};

const d = $input.item.json;

const sentimentEmoji = { 'Bullish':'🟢','Bearish':'🔴','Neutral':'🟡' }[d.sentiment] || '⚪';
const credibilityEmoji = { 'High':'✅','Medium':'⚠️','Low':'❌' }[d.credibility] || '❓';
const coinsText = d.coins_mentioned && d.coins_mentioned.length > 0 ? d.coins_mentioned.join(', ') : 'N/A';
const parseWarning = d.parse_ok === false ? '\n⚠️ _AI response parse error - ข้อมูลอาจไม่ครบ_' : '';

const message = [
  `📝 ${d.summary_th}`,
  ``,
  `💰 Coins: ${coinsText}`,
  ``,
  `${credibilityEmoji} Credibility: **${d.credibility}**`,
  ``,
].join('\n');

const finalMessage = message.length > 1900 ? message.slice(0, 1897) + '...' : message;

return { json: { ...d, telegram_message: finalMessage } };
